            if hasattr(var, 'agent_ops_agent_id') and getattr(var, 'agent_ops_agent_id'):
                logger.debug('LLM call from agent named: %s', getattr(var, 'agent_ops_agent_name'))
                return getattr(var, 'agent_ops_agent_id')
    return None


